-- Every US severe-weather event -- deaths, injuries, property/crop damage, location -- 1.8M records.
-- Auto-generated by scripts/gen_evidence_pages.py: 1,780,730 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "YEAR" as year, count(*) as records
from THE_LIBRARY.ENERGY_ENVIRONMENT.STORM_EVENTS
group by 1
order by 1
limit 1000
